#!/usr/bin/env bash

# Generated by the wan_gateway_nodes blueprint from a single values.yaml - do not
# hand-edit per node. If a value needs to change, edit values.yaml and regenerate.

export GS_LICENSE="{{gigaspaces.license}}"

export JAVA_HOME="{{java.home}}"
export PATH="$JAVA_HOME/bin:$PATH"

export GS_HOME="{{gigaspaces.home}}"

export GS_NIC_ADDRESS="$(hostname -i)"

export SITE_A_NAME="{{siteA.gatewayName}}"
export SITE_A_HOST="{{siteA.host}}"
export SITE_A_SPACE_NAME="{{siteA.spaceName}}"

export SITE_B_NAME="{{siteB.gatewayName}}"
export SITE_B_HOST="{{siteB.host}}"
export SITE_B_SPACE_NAME="{{siteB.spaceName}}"

export GATEWAY_DISCOVERY_PORT="{{gateway.discoveryPort}}"
export GATEWAY_COMMUNICATION_PORT="{{gateway.communicationPort}}"

export SPACE_MANAGER_LOOKUP_PORT="{{space.managerLookupPort}}"

export GS_OPTIONS_EXT="-Dcom.gs.multicast.enabled=false"
